inline QJsonObject scan(const QByteArray &bytes,const std::atomic_bool &cancel){auto catalog=parse(bytes,cancel);QJsonArray rows,notes;if(!catalog.error.isEmpty())return {{"notes",QJsonArray{catalog.error}}};for(const auto &p:catalog.parts){qint64 corners=0,faces=0;for(auto s:p.strips){corners+=s.count;faces+=s.count-2;}rows.append(QJsonObject{{"name",QString("MSR %1 / 0x%2 / material %3").arg(catalog.retail?"retail track":p.track?"alpha track":"alpha vehicle primary LOD").arg(p.record,0,16).arg(p.material)},{"profileId",p.track?(catalog.retail?"native-msr-retail-track":"native-msr-alpha-track"):"native-msr-alpha-car"},{"profileName","MSR independent strips"},{"nativeDecoder",true},{"objectOffset",QString::number(p.record)},{"msrMaterial",p.material},{"settings",QJsonObject{{"vertexCount",corners},{"indexCount",faces*3}}},{"basis","Validated MSR records and independent strip boundaries. Local centers applied; per-corner UVs retained. Texture IDs resolve to embedded or sibling Dreamcast textures during preview. Retail track headers use a separate validated entry point; PGR variants use separate decoders."}});}if(!rows.isEmpty())notes.append(QString("MSR: %1 material groups. Vehicle import is the primary LOD only; tracks omit %2 empty nodes. Dreamcast textures resolve during preview; keep DYT/NTT companions beside track files.").arg(rows.size()).arg(catalog.omitted));return {{"candidates",rows},{"notes",notes}};}
inline QByteArray decodedSource(ReadRequest source,const PatchList &patches,const std::atomic_bool &cancel,QString &error){auto bytes=NativeResources::read(source,patches,0,source.expectedSize,cancel,error,AssetMemory::bytes()/4);if(!error.isEmpty())return {};if(bytes.startsWith(QByteArray::fromHex("50616b1b"))){auto resources=NativeResources::inspect(source,patches,cancel);auto entries=resources["entries"].toArray();if(entries.size()!=1){error=resources["error"].toString("Invalid MSR Pak envelope.");return {};}auto result=NativeResources::extract(source,patches,entries.first().toObject(),cancel);error=result.error;return result.bytes;}return bytes;}
struct Session {QMutex mutex;QByteArray bytes,textureBytes;Catalog catalog;QVector<MsrTextures::Texture> textures;QMap<int,QImage> images;ReadRequest companion;QString textureError;};
